<?php
$pageTitle='Budget Planner';$theme='gold';require_once 'includes/db.php';$planId=(int)($_GET['plan_id']??0);$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){$planId=(int)$_POST['plan_id'];$title=trim($_POST['title']??'');$estimated=(float)$_POST['estimated'];$actual=(float)$_POST['actual'];if($title!==''){$q=$pdo->prepare('INSERT INTO budget_items(plan_id,title,estimated,actual) VALUES(?,?,?,?)');$q->execute([$planId,$title,$estimated,$actual]);$message='Expense added.';}}
$plan=$planId?$pdo->query('SELECT * FROM event_plans WHERE id='.$planId)->fetch():null;if(!$plan){$plan=$pdo->query('SELECT * FROM event_plans ORDER BY id DESC LIMIT 1')->fetch();$planId=$plan['id']??0;}$items=$planId?$pdo->query('SELECT * FROM budget_items WHERE plan_id='.$planId.' ORDER BY id DESC')->fetchAll():[];$estimated=array_sum(array_column($items,'estimated'));$actual=array_sum(array_column($items,'actual'));$remaining=($plan['budget']??0)-$actual;include 'includes/header.php';
?>
<section class="py-5"><div class="container"><div class="section-title"><p class="eyebrow" style="color:var(--gold)">BUDGET CONTROL</p><h2>Keep your event spending under control</h2><p class="text-muted">Add estimated and actual costs and see what remains from your budget.</p></div><?php if(!$plan):?><div class="alert alert-info">Create an event plan first.</div><a class="btn btn-brand" href="plan-event.php">Plan My Event</a><?php else:?><div class="row g-4 mb-4"><div class="col-md-4"><div class="content-card p-4"><small>Total Budget</small><h3>PKR <?=number_format($plan['budget'])?></h3></div></div><div class="col-md-4"><div class="content-card p-4"><small>Actual Spent</small><h3>PKR <?=number_format($actual)?></h3></div></div><div class="col-md-4"><div class="content-card p-4"><small>Remaining</small><h3 class="<?= $remaining<0?'text-danger':''?>">PKR <?=number_format($remaining)?></h3></div></div></div><div class="row g-4"><div class="col-lg-7"><div class="content-card p-4"><h4>Expenses</h4><?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><div class="table-responsive"><table class="table"><thead><tr><th>Item</th><th>Estimated</th><th>Actual</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=htmlspecialchars($i['title'])?></td><td>PKR <?=number_format($i['estimated'])?></td><td>PKR <?=number_format($i['actual'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-5"><div class="content-card p-4"><h4>Add Expense</h4><form method="post"><input type="hidden" name="plan_id" value="<?=$planId?>"><label class="form-label">Expense</label><input name="title" class="form-control mb-3" required><label class="form-label">Estimated</label><input name="estimated" type="number" class="form-control mb-3" value="0"><label class="form-label">Actual</label><input name="actual" type="number" class="form-control mb-3" value="0"><button class="btn btn-brand w-100">Add Expense</button></form></div></div></div><?php endif;?></div></section>
